"""Write the auditable validation-only aggregation repair report."""
from __future__ import annotations
import argparse, json
from pathlib import Path

def load(path):
    p=Path(path) if path else None
    return json.loads(p.read_text()) if p and p.exists() else None

def main() -> None:
    p=argparse.ArgumentParser(); p.add_argument("--v1-report",type=Path,required=True); p.add_argument("--teacher-forced",type=Path,required=True); p.add_argument("--development-metrics",type=Path,required=True); p.add_argument("--development-protocol",type=Path,required=True); p.add_argument("--blind-metrics"); p.add_argument("--blind-teacher-forced"); p.add_argument("--final-decision",type=Path,required=True); p.add_argument("--output",type=Path,required=True); a=p.parse_args()
    dev=load(a.development_metrics); protocol=load(a.development_protocol); teacher=load(a.teacher_forced); final=load(a.final_decision); lines=["# SCIZOR Stage 3F-R Aggregation Repair Report","","> This report treats validation strictly as the development set. No blind benchmark was read or generated after the fixed development gate failed.","","## Decision","",f"- Final decision: `{final['decision']}`",f"- Stage3 v1 decision preserved: `{final['stage3_v1_decision_preserved']}`",f"- Aggregation repair attempted: `{final['aggregation_repair_attempted']}`",f"- Blind generated: `{final['blind_generated']}`",f"- Failed rules: `{', '.join(final['failed_rules'])}`","","## Complete Teacher-Forced Diagnostic","",f"- Pairs: `{teacher['pair_count']}`; effective pairs: `{teacher['effective_pair_count']}`",f"- Full AUROC: `{teacher['full']['auroc']:.6f}`; AUPRC: `{teacher['full']['auprc']:.6f}`",f"- Full score Spearman: `{teacher['full']['score_spearman']:.6f}`","","## Fixed Development Matrix","","| method | source | AUROC | AUPRC | FAR | effective recall | Can AUROC | Square AUROC | eligible |","|---|---|---:|---:|---:|---:|---:|---:|:---:|"]
    for r in dev["methods"]: lines.append(f"| {r['method_id']} | {r['source']} | {r['pair_auroc']:.6f} | {r['pair_auprc']:.6f} | {r['no_effect_far'] if r['no_effect_far'] is not None else 'NA'} | {r['effective_recall'] if r['effective_recall'] is not None else 'NA'} | {r['can_auroc'] if r['can_auroc'] is not None else 'NA'} | {r['square_auroc'] if r['square_auroc'] is not None else 'NA'} | {r['eligible']} |")
    lines += ["","## Scope And Stop Rule","","The candidate replacement baseline remained above the verifier gate, and the complete teacher-forced full AUROC met the required threshold. The fixed aggregation methods did not satisfy the development gate, so the protocol stops before blind generation. No formula, threshold, source, checkpoint, proposer, oracle, label, or benchmark was changed after this failure.","", "## Preserved v1 Evidence", "", "The original Stage 3 v1 report is included under `baseline_v1/`; its final decision remains `SWITCH_TO_COVERAGE_CONSTRAINED_SOFT_SCIZOR`.","", "## Reproducibility", "", "Development input tables and their derived score tables remain outside this lightweight package because they are parquet artifacts. The package contains the deterministic source code, protocol configuration, summaries, metrics, and baseline evidence needed to audit the decision."]
    a.output.parent.mkdir(parents=True,exist_ok=True); a.output.write_text("\n".join(lines)+"\n",encoding="utf-8")
if __name__ == "__main__": main()
